    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("ordinary package is legal", true, PackageNameNormalizer.isLegal("com.example.util"));
        check("empty segment is illegal", false, PackageNameNormalizer.isLegal("com..util"));
        check("segment starting with a digit is illegal", false, PackageNameNormalizer.isLegal("com.3d.util"));
        check("reserved word is illegal", false, PackageNameNormalizer.isLegal("com.new.util"));
        check("domain reversed and lower cased", "com.example", PackageNameNormalizer.fromDomain("Example.COM"));
        check("hyphen becomes underscore", "com.my_site", PackageNameNormalizer.fromDomain("my-site.com"));
        check("leading digit fixed", "com._3m", PackageNameNormalizer.fromDomain("3m.com"));
        check("reserved word fixed", "com.example.new_", PackageNameNormalizer.fromDomain("new.example.com"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
