public class PackageNameNormalizer {

    /** Provided -- do not edit. Words a package segment may not be. */
    static final java.util.Set<String> RESERVED = java.util.Set.of(
            "class", "int", "new", "package", "static", "void", "for", "if", "native", "final", "public");

    public static boolean isLegal(String packageName) {
        if (packageName == null || packageName.isEmpty()) {
            return false;
        }
        for (String segment : packageName.split("\\.", -1)) {
            if (!isLegalSegment(segment)) {
                return false;
            }
        }
        return true;
    }

    private static boolean isLegalSegment(String segment) {
        if (segment.isEmpty() || RESERVED.contains(segment)) {
            return false;
        }
        char first = segment.charAt(0);
        if (!Character.isLetter(first) && first != '_' && first != '$') {
            return false;
        }
        for (int i = 1; i < segment.length(); i++) {
            char c = segment.charAt(i);
            if (!Character.isLetterOrDigit(c) && c != '_' && c != '$') {
                return false;
            }
        }
        return true;
    }

    public static String fromDomain(String domain) {
        if (domain == null || domain.isEmpty()) {
            return "";
        }
        String[] parts = domain.split("\\.", -1);
        StringBuilder result = new StringBuilder();
        for (int i = parts.length - 1; i >= 0; i--) {
            if (result.length() > 0) {
                result.append('.');
            }
            result.append(cleanSegment(parts[i]));
        }
        return result.toString();
    }

    private static String cleanSegment(String part) {
        StringBuilder segment = new StringBuilder();
        String lower = part.toLowerCase(java.util.Locale.US);
        for (int i = 0; i < lower.length(); i++) {
            char c = lower.charAt(i);
            segment.append(Character.isLetterOrDigit(c) ? c : '_');
        }
        if (segment.length() > 0 && Character.isDigit(segment.charAt(0))) {
            segment.insert(0, '_');
        }
        if (RESERVED.contains(segment.toString())) {
            segment.append('_');
        }
        return segment.toString();
    }
}
